WITH cleaned AS (SELECT id, carrier, shipped_date, delivered_date, status, CASE WHEN status = 'IN_TRANSIT' THEN 1 ELSE 0 END AS is_in_transit, ROUND(cost * 0.9, 2) AS cost_scaled FROM shipments WHERE delivered_date > TO_DATE('2023-08-21')) SELECT id, carrier, shipped_date, status, cost_scaled, LEAD(cost_scaled, 1) OVER (PARTITION BY status ORDER BY cost_scaled, id) AS next_cost_scaled, LAG(is_in_transit, 2) OVER (PARTITION BY carrier ORDER BY is_in_transit, id) AS prev_is_in_transit, NTILE(4) OVER (PARTITION BY carrier ORDER BY cost_scaled, id) AS cost_scaled_bucket FROM cleaned
